//! 🧪️ A native Pack receiver preserves actual source custody and physically settles before handoff.
use super::*;
use crate::original_steps::{begin,forgotten,retired,grant_of,birth_grant};
use semio_framework_job::{OriginalConstructionAdmission,OriginalJobFixtureCaller,OriginalJobDecodeOwner,OperationId,Generation,default_now_us};
use semio_framework_value::{RetainedCloneGrant,retirement::controlled::ControlledRetirement};
fn finish(caller:&mut OriginalJobFixtureCaller,decoder:&mut OriginalJobDecodeOwner){for index in 0..4096{if decoder.terminal_is_empty(){return}let grant=grant_of(decoder.retirement_demands(4096).unwrap());caller.turn(grant,|cx|cx.with_original_retirement(|cx|{decoder.close_on_source(cx)?;Ok(())})).unwrap();assert!(index<4095,"original decoder close stalled");}}
fn bind(caller:&mut OriginalJobFixtureCaller,decoder:&mut OriginalJobDecodeOwner){let stock=semio_framework_value::RetainedCloneGrant{maximum_items:1<<20,maximum_copy_bytes:1<<24,maximum_capacity_bytes:1<<24,maximum_release_bytes:1<<24,maximum_depth:128};for _ in 0..16{if caller.turn(stock,|cx|Ok(decoder.admit_step(cx)?)).unwrap(){break}}assert!(decoder.source_loan_admitted(),"original decoder source loan is admitted before any birth");}
fn turn<R>(caller:&mut OriginalJobFixtureCaller,decoder:&mut OriginalJobDecodeOwner,g:RetainedCloneGrant,run:impl FnOnce(&mut StepContext<'_>)->Result<R,OriginalTurnFailure>)->R{let(result,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||caller.turn_with_decoder(g,decoder,run));let p=caller.receipt();assert_eq!((heap.requested_bytes,heap.released_bytes),(p.retained_capacity_bytes,p.released_bytes),"actual original Pack receipt {p:?}");result.unwrap()}
fn born_within<O>(caller:&mut OriginalJobFixtureCaller,decoder:&mut OriginalJobDecodeOwner,d:RetirementDemand,mut admit:impl FnMut(&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>){let grant=birth_grant::<O>(d).unwrap();for index in 0..64{let mut snap=None;let mut probe=|cx:&mut StepContext<'_>|{let before=(cx.should_yield(),cx.retirement_should_yield(),cx.is_cancelled(),cx.retained_grant(),cx.fuel_remaining());let r=admit(cx);snap=Some((before,r.as_ref().ok().copied(),cx.retained_progress()));r};let done=turn(caller,decoder,grant,&mut probe);if index<5{eprintln!("[DEBUG] born turn {index} {snap:?}");}if done{return}assert!(index<63,"original birth did not settle on its exact quote")}}
#[test]
fn original_pack_typed_receiving_settles_every_original_before_unique_handoff(){
 let law:serde_json::Value=serde_json::from_str(include_str!("🔣️.json")).unwrap();let text=law["text"].as_str().unwrap().repeat(law["repeat"].as_u64().unwrap()as usize);let oracle:serde_json::Value=serde_json::from_str(&serde_json::to_string(&text).unwrap()).unwrap();
 for cut in law["cancelPrefixes"].as_array().unwrap().iter().map(|n|Some(n.as_u64().unwrap()as usize)).chain([None]){
  let g=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:4096,maximum_capacity_bytes:1<<24,maximum_release_bytes:1<<24,maximum_depth:4096};let mut caller=OriginalJobFixtureCaller::admit(OperationId(381),Generation(7),RetainedCloneGrant{maximum_items:1<<30,maximum_copy_bytes:1<<30,maximum_capacity_bytes:1<<29,maximum_release_bytes:1<<29,maximum_depth:4096},default_now_us,u64::MAX,1<<30);let mut decoder=OriginalJobDecodeOwner::empty();bind(&mut caller,&mut decoder);
  let mut allow=|_|true;let mut encode=semio_framework_value::NativeEncodeControl::new(1<<24,&mut allow);let mut raw=semio_framework_pack_record::intrinsic::encode_body(&DslValue::String(text.clone()),&Default::default(),&mut encode).unwrap();let pointer=raw.as_ptr();let length=raw.len();let mut owner=None;let mut admission=OriginalConstructionAdmission::default();let mut failure=None;let d=RetirementDemand{capacity_bytes:size_of::<OriginalPackReceiving<String>>(),..fixed::<OriginalPackReceiving<String>>()};
  for axis in 0..4{let mut denied=g;match axis{0=>denied.maximum_items=0,1=>denied.maximum_copy_bytes=d.copy_bytes-1,2=>denied.maximum_capacity_bytes=d.capacity_bytes-1,3=>denied.maximum_depth=0,_=>unreachable!()}turn(&mut caller,&mut decoder,denied,|cx|{assert!(!OriginalPackReceiving::<String>::admit(&mut raw,Default::default(),cx,&mut admission,&mut failure,&mut owner)?);Ok(())});assert!(owner.is_none());assert_eq!((raw.as_ptr(),raw.len()),(pointer,length));}
  born_within::<Box<OriginalPackReceiving<String>>>(&mut caller,&mut decoder,OriginalPackReceiving::<String>::admission_demands(),|cx|OriginalPackReceiving::<String>::admit(&mut raw,Default::default(),cx,&mut admission,&mut failure,&mut owner));assert!(raw.is_empty());
  for index in 0..262144{if cut==Some(index){break}let ready=turn(&mut caller,&mut decoder,g,|cx|owner.as_mut().unwrap().advance(cx));if index==0{assert_eq!(owner.as_ref().unwrap().parser.as_ref().unwrap().input().unwrap().as_ptr(),pointer);}if ready{break}assert!(index<262143,"original Pack receiving did not settle");}
  let mut output=None;if cut.is_none(){turn(&mut caller,&mut decoder,g,|cx|{assert!(owner.as_mut().unwrap().take(cx,&mut output)?);Ok(())});assert_eq!(serde_json::Value::String(output.as_ref().unwrap().clone()),oracle);}else{caller.cancel().cancel_now();}
  for index in 0..262144{if owner.as_ref().unwrap().terminal_is_empty(){break}turn(&mut caller,&mut decoder,g,|cx|cx.with_original_retirement(|cx|owner.as_mut().unwrap().close_step(cx)));assert!(index<262143,"original Pack cancellation did not settle");}
  turn(&mut caller,&mut decoder,g,|cx|cx.with_original_retirement(|cx|{let d=OriginalPackReceiving::<String>::release_demands();forgotten(cx,d,||{owner.take();})?;Ok(())}));
  if let Some(output)=output{let mut close=ControlledRetirement::new(output).map_err(|(error,_)|error).unwrap();for index in 0..262144{if close.terminal_is_empty(){break}turn(&mut caller,&mut decoder,g,|cx|cx.with_original_retirement(|cx|{let d=close.selected_demand(4096)?;retired(cx,d,|effect|{let body=effect.grant().maximum_copy_bytes;close.step(body,effect)})?;Ok(())}));assert!(index<262143);}}
  finish(&mut caller,&mut decoder);caller.retire_exact();
 }
}

fn receive_authored<T:NativeReceive<DslValue>+Sync+semio_framework_value::ToValue+PartialEq+std::fmt::Debug>(value:T){receive_authored_source(value,false)}
fn receive_authored_source<T:NativeReceive<DslValue>+Sync+semio_framework_value::ToValue+PartialEq+std::fmt::Debug>(value:T,original_value:bool){
 use semio_framework_value::ToValue;
 let input=value.to_value();let mut raw=if original_value{Vec::new()}else{let mut allow=|_|true;let mut encode=semio_framework_value::NativeEncodeControl::new(1<<24,&mut allow);semio_framework_pack_record::intrinsic::encode_body(&input,&Default::default(),&mut encode).unwrap()};let mut caller=OriginalJobFixtureCaller::admit(OperationId(383),Generation(9),RetainedCloneGrant{maximum_items:1<<30,maximum_copy_bytes:1<<30,maximum_capacity_bytes:1<<29,maximum_release_bytes:1<<29,maximum_depth:4096},default_now_us,u64::MAX,1<<30);let mut decoder=OriginalJobDecodeOwner::empty();bind(&mut caller,&mut decoder);let g=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:4096,maximum_capacity_bytes:1<<24,maximum_release_bytes:1<<24,maximum_depth:4096};let mut owner=None;let mut admission=OriginalConstructionAdmission::default();let mut failure=None;let mut original=Some(input.clone());born_within::<Box<OriginalPackReceiving<T>>>(&mut caller,&mut decoder,OriginalPackReceiving::<T>::admission_demands(),|cx|if original_value{OriginalPackReceiving::<T>::admit_value(&mut original,cx,&mut admission,&mut failure,&mut owner)}else{OriginalPackReceiving::<T>::admit(&mut raw,Default::default(),cx,&mut admission,&mut failure,&mut owner)});for index in 0..262144{if turn(&mut caller,&mut decoder,g,|cx|owner.as_mut().unwrap().advance(cx)){break}assert!(index<262143,"authored typed transaction field stalled");}let mut output=None;turn(&mut caller,&mut decoder,g,|cx|{assert!(owner.as_mut().unwrap().take(cx,&mut output)?);Ok(())});assert_eq!(output.as_ref().unwrap(),&value);assert_eq!(output.as_ref().unwrap().to_value(),input);
 for index in 0..262144{if owner.as_ref().unwrap().terminal_is_empty(){break}turn(&mut caller,&mut decoder,g,|cx|cx.with_original_retirement(|cx|owner.as_mut().unwrap().close_step(cx)));assert!(index<262143);}turn(&mut caller,&mut decoder,g,|cx|cx.with_original_retirement(|cx|{let d=OriginalPackReceiving::<T>::release_demands();forgotten(cx,d,||{owner.take();})?;Ok(())}));let mut close=RetainedCloneClose::default();for index in 0..262144{if output.is_none()&&close.is_empty(){break}turn(&mut caller,&mut decoder,g,|cx|cx.with_original_retirement(|cx|{let d=close.next_owner_demands::<T>(output.is_some(),&None,4096)?;retired(cx,d,|effect|begin(&mut close,&mut output,effect))?;Ok(())}));assert!(index<262143);}finish(&mut caller,&mut decoder);caller.retire_exact();
}
#[test]fn original_value_receives_without_reparsing(){receive_authored_source("original λ🙂".repeat(2049),true)}
#[test]fn original_media_descriptor_receives_its_declared_wire_fields(){
 use semio_framework_value::ToValue;let descriptor=semio_plugin_decl_app::MediaArtifactDescriptor{edge_id:Some("edge".into()),port_id:Some("image:in".into()),kind_id:None,media_type:Some(semio_framework::MediaType{class:semio_framework::MediaClass::TwoD,form:semio_framework::MediaForm::Raster}),wire:semio_framework::MediaWireFormat::Intrinsic{schema:"image.schema".into()},blob_hash:None};let oracle=serde_json::json!({"edgeId":"edge","portId":"image:in","mediaType":{"class":"twoD","form":"raster"},"wire":{"kind":"intrinsic","schema":"image.schema"}});assert_eq!(serde_json::to_value(descriptor.to_value()).unwrap(),oracle);receive_authored(descriptor)
}
#[test]fn original_value_denial_keeps_the_caller_source(){
 let g=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:4096,maximum_capacity_bytes:1<<24,maximum_release_bytes:1<<24,maximum_depth:4096};let mut caller=OriginalJobFixtureCaller::admit(OperationId(384),Generation(10),RetainedCloneGrant{maximum_items:1<<30,maximum_copy_bytes:1<<30,maximum_capacity_bytes:1<<29,maximum_release_bytes:1<<29,maximum_depth:4096},default_now_us,u64::MAX,1<<30);let mut decoder=OriginalJobDecodeOwner::empty();bind(&mut caller,&mut decoder);let mut input=Some(DslValue::String("retained source".into()));let mut owner=None;let mut admission=OriginalConstructionAdmission::default();let mut failure=None;let mut denied=g;denied.maximum_items=0;turn(&mut caller,&mut decoder,denied,|cx|{assert!(!OriginalPackReceiving::<String>::admit_value(&mut input,cx,&mut admission,&mut failure,&mut owner)?);Ok(())});assert_eq!(input,Some(DslValue::String("retained source".into())));assert!(owner.is_none());finish(&mut caller,&mut decoder);caller.retire_exact();
}
#[test]fn original_intrinsic_pack_returns_its_actual_value_and_closes_cancelled_prefixes(){
 let oracle:serde_json::Value=serde_json::from_str(r#"{"text":"λ🙂","rows":[1,true,null]}"#).unwrap();let original=DslValue::from(oracle.clone());
 for cancel in [false,true]{let g=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:4096,maximum_capacity_bytes:1<<24,maximum_release_bytes:1<<24,maximum_depth:4096};let mut caller=OriginalJobFixtureCaller::admit(OperationId(385),Generation(11),RetainedCloneGrant{maximum_items:1<<30,maximum_copy_bytes:1<<30,maximum_capacity_bytes:1<<29,maximum_release_bytes:1<<29,maximum_depth:4096},default_now_us,u64::MAX,1<<30);let mut decoder=OriginalJobDecodeOwner::empty();bind(&mut caller,&mut decoder);let mut allow=|_|true;let mut control=semio_framework_value::NativeEncodeControl::new(1<<24,&mut allow);let mut bytes=semio_framework_pack_record::intrinsic::encode_body(&original,&Default::default(),&mut control).unwrap();let mut owner=None;let mut admission=OriginalConstructionAdmission::default();let mut failure=None;born_within::<Box<OriginalIntrinsicReceiving>>(&mut caller,&mut decoder,OriginalIntrinsicReceiving::admission_demands(),|cx|OriginalIntrinsicReceiving::admit(&mut bytes,Default::default(),cx,&mut admission,&mut failure,&mut owner));for index in 0..262144{if cancel&&index==3{caller.cancel().cancel_now();break}if turn(&mut caller,&mut decoder,g,|cx|owner.as_mut().unwrap().advance(cx)){break}assert!(index<262143)}let mut output=None;if !cancel{turn(&mut caller,&mut decoder,g,|cx|{assert!(owner.as_mut().unwrap().take(cx,&mut output)?);Ok(())});assert_eq!(serde_json::to_value(output.as_ref().unwrap()).unwrap(),oracle)}for index in 0..262144{if owner.as_ref().unwrap().terminal_is_empty(){break}turn(&mut caller,&mut decoder,g,|cx|cx.with_original_retirement(|cx|owner.as_mut().unwrap().close_step(cx)));assert!(index<262143)}turn(&mut caller,&mut decoder,g,|cx|cx.with_original_retirement(|cx|{let d=OriginalIntrinsicReceiving::release_demands();forgotten(cx,d,||{owner.take();})?;Ok(())}));let mut close=RetainedCloneClose::default();for _ in 0..262144{if output.is_none()&&close.is_empty(){break}turn(&mut caller,&mut decoder,g,|cx|cx.with_original_retirement(|cx|{let d=close.next_owner_demands::<DslValue>(output.is_some(),&None,4096)?;retired(cx,d,|effect|begin(&mut close,&mut output,effect))?;Ok(())}));}assert!(output.is_none()&&close.is_empty());finish(&mut caller,&mut decoder);caller.retire_exact();}
}
#[test]fn original_transaction_origin_and_child_groups_receive_their_authored_wire_fields(){
 use semio_os_kernel as protocol;
 receive_authored(protocol::MutationOrigin::Owner);
 receive_authored(protocol::MutationOrigin::Contributed{plugin_id:"contributor λ🙂".repeat(2049),mutation_id:protocol::SchemaId("authored-operation".into()),payload_hash:protocol::PayloadHash([7;32])});
 receive_authored(protocol::MutationOrigin::Transaction{initiator:protocol::ForeignTarget{artifact_id:"original-initiator".into(),artifact_kind:"s.test.source".into(),dialect:Some("s.test.source@1#full".into())}});
 let label=semio_ui_locale::LocalizedLabel::from_fn(|terminology,locale|format!("{}:{}:λ🙂",terminology.as_str(),locale.as_str()));let child=semio_plugin_decl_emission::ChildEmit{genesis:Some(semio_plugin_decl_emission::ChildEmitGenesis{reference:semio_framework_artifact_reference::ArtifactRef{artifact_id:"original-genesis".into(),dialect:semio_framework_artifact_reference::ArtifactDialect{artifact_kind:"s.test.child".into(),standard:"1".into(),subset:"full".into()}},initial_pack:vec![1,2,127,255]}),owner:"parent/owner".into(),slot:"children".into(),child_id:"original-child".into(),ops:vec![vec![1,2],vec![3]],op_schema:protocol::SchemaId("s.test.child#edit".into()),labels:vec![label]};receive_authored(vec![child]);
}
